prompt --application/shared_components/security/authorizations/is_hr_admin
begin
wwv_flow_imp_shared.create_security_scheme(
 p_id=>wwv_flow_imp.id(5720216564010611318)
,p_name=>'IS_HR_ADMIN'
,p_static_id=>'is-hr-admin'
,p_scheme_type=>'NATIVE_EXISTS'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'sql_query', wwv_flow_string.join(wwv_flow_t_varchar2(
    'SELECT 1',
    '  FROM tms_roles r',
    '  JOIN tms_employee_roles er',
    '    ON er.role_id = r.role_id',
    ' WHERE r.role_code = ''HR_ADMIN''',
    '   AND er.employee_id = :APP_EMPLOYEE_ID')))).to_clob
,p_version_scn=>'SH256:S0Nz1i9vRdW8WuU9Sic2wJpYRAuMolIP_aOwxB_zIcE'
,p_caching=>'BY_USER_BY_SESSION'
);
