,p_polling_interval=>'FREQ=DAILY;INTERVAL=1;BYHOUR=7;BYMINUTE=0'
,p_polling_status=>'DISABLED'
,p_result_type=>'ROWS'
,p_location=>'LOCAL'
,p_query_type=>'SQL'
,p_query_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT e.employee_id,',
'       e.first_name || '' '' || e.last_name AS employee_name,',
'       e.hire_date,',
'       ADD_MONTHS(e.hire_date,',
'           apex_app_setting.get_value(''PROBATION_MONTHS'')) AS probation_end',
'  FROM tms_employees e',
' WHERE e.status = ''Active''',
'   AND ADD_MONTHS(e.hire_date,',
