prompt --application/shared_components/security/authentications/ess_authentication
begin
wwv_flow_imp_shared.create_authentication(
 p_id=>wwv_flow_imp.id(5719985656520565400)
,p_name=>'ESS - Authentication'
,p_static_id=>'ess-authentication'
,p_scheme_type=>'NATIVE_CUSTOM'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'authentication_function', 'authenticate',
  'enable_legacy_attributes', 'N')).to_clob
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'FUNCTION authenticate (',
'  p_username VARCHAR2,',
'  p_password VARCHAR2',
') RETURN BOOLEAN',
'IS',
'  l_count NUMBER;',
'BEGIN',
'  IF p_username IS NULL OR p_password IS NULL THEN',
'    RETURN FALSE;',
'  END IF;',
'',
'  SELECT COUNT(*) INTO l_count',
'    FROM tms_employees',
'   WHERE UPPER(email) = UPPER(p_username)',
'     AND status = ''Active''',
'     AND password = hash_password(UPPER(p_username), p_password);',
'  RETURN l_count = 1;',
'END authenticate;',
''))
,p_use_secure_cookie_yn=>'N'
,p_ras_mode=>0
,p_version_scn=>'SH256:3jzaKbRGeIe7rozbQfT8NaIOwRmoXCVzTPdCDun6H5Y'
);
end;
/
