wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(4483114036135274860)
,p_plug_name=>'Your Onboarding Progress'
,p_static_id=>'your-onboarding-progress'
,p_title=>'Your Onboarding Progress'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4075786578761660127
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    COUNT(*) AS value,',
'    ''Tasks Pending'' AS label,',
'    ''Open onboarding tasks'' AS description,',
'    ''fa-tasks'' AS icon,',
'    NULL AS badge',
'FROM tms_onboarding_tasks',
'WHERE employee_id = (',
'          SELECT employee_id',
'          FROM tms_employees',
'          WHERE UPPER(email) = UPPER(:APP_USER)',
'      )',
'  AND status NOT IN (''Completed'', ''Cancelled'')',
'',
'UNION ALL',
'',
'SELECT',
'    COUNT(*) AS value,',
'    ''HR Documents Completed'' AS label,',
'    ''Completed HR document tasks'' AS description,',
'    ''fa-file-check'' AS icon,',
'    NULL AS badge',
'FROM tms_onboarding_tasks',
'WHERE employee_id = (',
'          SELECT employee_id',
'          FROM tms_employees',
'          WHERE UPPER(email) = UPPER(:APP_USER)',
'      )',
'  AND status = ''Completed''',
'  AND category = ''HR Documents''',
'',
'UNION ALL',
'',
'SELECT',
'    NVL(',
'        (',
'            SELECT GREATEST(',
'                       0,',
'                       TRUNC(hire_date) - TRUNC(SYSDATE)',
'                   )',
'            FROM tms_employees',
'            WHERE UPPER(email) = UPPER(:APP_USER)',
'        ),',
'        0',
'    ) AS value,',
'    ''Days Until Start'' AS label,',
'    ''Days remaining before hire date'' AS description,',
'    ''fa-calendar'' AS icon,',
'    NULL AS badge',
'FROM dual',
'',
'UNION ALL',
'',
'SELECT',
'    NVL(',
'        (',
'            SELECT MAX(remaining)',
'            FROM tms_leave_balances',
'            WHERE employee_id = (',
'                      SELECT employee_id',
'                      FROM tms_employees',
'                      WHERE UPPER(email) = UPPER(:APP_USER)',
'                  )',
'              AND leave_type_id = 1',
'              AND year = EXTRACT(YEAR FROM SYSDATE)',
'        ),',
'        0',
'    ) AS value,',
'    ''Leave Days Available'' AS label,',
'    ''Current annual leave balance'' AS description,',
'    ''fa-umbrella'' AS icon,',
'    NULL AS badge',
'FROM dual',
''))
,p_template_component_type=>'REPORT'
,p_lazy_loading=>false
,p_plug_source_type=>'TMPL_THEME_42$METRIC_CARD'
,p_plug_query_num_rows=>15
,p_plug_query_num_rows_type=>'SET'
,p_show_total_row_count=>false
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'AVATAR_ALIGNMENT', 't-MetricCard-body--avatarAlignmentStart',
  'AVATAR_ICON', '&ICON.',
  'AVATAR_POSITION', 't-MetricCard-body--avatarPositionInline',
  'AVATAR_SHAPE', 't-Avatar--rounded',
  'AVATAR_STYLE', 't-MetricCard-avatar--subtle',
  'AVATAR_TYPE', 'icon',
  'DISPLAY_AVATAR', 'Y',
  'DISPLAY_BADGE', 'N',
  'LAYOUT', '4cols',
  'METRIC', '&VALUE.',
  'TITLE', '&LABEL.')).to_clob
);
