wwv_flow_imp_page.create_component_da_action(
 p_id=>wwv_flow_imp.id(6815793523764257144)
,p_button_id=>wwv_flow_imp.id(6081731896709620693)
,p_action_sequence=>10
,p_name=>'Execute Server-side Code'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_static_id=>'execute-server-side-code'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'language', 'PLSQL',
  'plsql_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'BEGIN',
    '    SELECT COUNT(*)',
    '      INTO :P1_OPEN_REQS',
    '      FROM tms_job_requisitions',
    '     WHERE status = ''Open'';',
    '',
    '    SELECT COUNT(*)',
    '      INTO :P1_NEW_CANDIDATES',
    '      FROM tms_candidates',
    '     WHERE applied_date >= TRUNC(SYSDATE, ''IW'')',
    '       AND applied_date < TRUNC(SYSDATE, ''IW'') + 7;',
    '',
    '    SELECT COUNT(*)',
    '      INTO :P1_PENDING_OFFERS',
    '      FROM tms_offers',
    '     WHERE status = ''Pending Approval'';',
    '',
    '    SELECT COUNT(*)',
