,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Execute Wizard Cancellation'
,p_static_id=>'execute-wizard-cancellation'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'IF APEX_COLLECTION.COLLECTION_EXISTS(''ONBOARDING_COLLECTION'') THEN',
'    APEX_COLLECTION.DELETE_COLLECTION(''ONBOARDING_COLLECTION'');',
'END IF;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(5665143135091453456)
,p_internal_uid=>5658201869331750213
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(5668368656208552055)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Finalize Onboarding Data'
,p_static_id=>'finalize-onboarding-data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_row1        apex_collections%ROWTYPE;',
'    v_contract    BLOB;',
'    v_taxform     BLOB;',
'    v_employee_id tms_employees.employee_id%TYPE;',
'BEGIN',
'    SELECT employee_id',
'    INTO   v_employee_id',
'    FROM   tms_employees',
'    WHERE  UPPER(email) = UPPER(:APP_USER);',
'',
'    SELECT *',
'    INTO   v_row1',
'    FROM   apex_collections',
'    WHERE  collection_name = ''ONBOARDING_COLLECTION''',
'    AND    seq_id = 1;',
'',
'    SELECT blob001',
'    INTO   v_contract',
'    FROM   apex_collections',
'    WHERE  collection_name = ''ONBOARDING_COLLECTION''',
'    AND    seq_id = 2;',
'',
'    SELECT blob001',
'    INTO   v_taxform',
'    FROM   apex_collections',
'    WHERE  collection_name = ''ONBOARDING_COLLECTION''',
'    AND    seq_id = 3;',
'',
'    UPDATE tms_employees',
'    SET    phone                   = v_row1.c004,',
'           emergency_contact_name  = v_row1.c005,',
'           emergency_contact_phone = v_row1.c006,',
'           home_address            = v_row1.c007,',
'           passport_blob           = v_row1.blob001,',
'           contract_blob           = v_contract,',
'           taxform_blob            = v_taxform',
'    WHERE  employee_id = v_employee_id;',
'',
'    INSERT INTO tms_onboarding_tasks (',
'        employee_id,',
'        task_name,',
'        category,',
'        due_date,',
'        status',
'    )',
'    SELECT v_employee_id,',
'           task_name,',
'           category,',
'           TRUNC(SYSDATE) + days_to_complete,',
'           ''Pending''',
'    FROM tms_onboarding_task_templates',
'    WHERE job_id = (',
'        SELECT job_id',
'        FROM tms_employees',
'        WHERE employee_id = v_employee_id',
'    );',
'',
'    IF APEX_COLLECTION.COLLECTION_EXISTS(''ONBOARDING_COLLECTION'') THEN',
'        APEX_COLLECTION.DELETE_COLLECTION(''ONBOARDING_COLLECTION'');',
'    END IF;',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Logged-in account does not match an employee record: '' || :APP_USER',
'        );',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>5658201729350750212
);
end;
