prompt --application/deployment/install/install_ll16_scriptadditions
begin
wwv_flow_imp.g_varchar2_table := wwv_flow_imp.empty_varchar2_table;
wwv_flow_imp.g_varchar2_table(1) := ' begin'||wwv_flow.LF||
'     EXECUTE IMMEDIATE'||wwv_flow.LF||
'        ''DROP TABLE TMS_EMPLOYEE_CHECKINS CASCADE CONSTRAINTS PURGE'';'||wwv_flow.LF||
'';
wwv_flow_imp.g_varchar2_table(2) := ' end;'||wwv_flow.LF||
' /'||wwv_flow.LF||
' '||wwv_flow.LF||
'  CREATE TABLE "TMS_EMPLOYEE_CHECKINS" '||wwv_flow.LF||
'   (	"CHECKIN_ID" NUMBER GENERATED BY DEFAULT AS ';
wwv_flow_imp.g_varchar2_table(3) := 'IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORD';
wwv_flow_imp.g_varchar2_table(4) := 'ER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, '||wwv_flow.LF||
'	"EMPLOYEE_ID" NUMBER NOT NULL ENABLE, '||wwv_flow.LF||
'	"OVERALL_RA';
wwv_flow_imp.g_varchar2_table(5) := 'TING" NUMBER, '||wwv_flow.LF||
'	"MANAGER_SUPPORT_RATING" NUMBER, '||wwv_flow.LF||
'	"ONBOARDING_RATING" NUMBER, '||wwv_flow.LF||
'	"COMMENTS" VARCHAR2';
wwv_flow_imp.g_varchar2_table(6) := '(2000), '||wwv_flow.LF||
'	"CREATED_AT" TIMESTAMP (6) DEFAULT SYSTIMESTAMP, '||wwv_flow.LF||
